//! MESH variant parity (Item 4d, 2026-11-21): Rust
//! columns_mesh stripper and absorber against the Python
//! columns_mesh_variants solvers on the cases of
//! python/test_mesh_variants.py (pentane/hexane/heptane,
//! temperature-dependent enthalpies, pressure 150000 Pa).
//! Locally verified only: no ChemCAD anchor exists for these
//! variants.
//!
//! Reference values were generated by running the Python
//! solvers on those cases on 2026-11-21: stage temperatures T
//! in kelvin (K), compositions (mole fractions, dimensionless),
//! liquid rates L and vapour rates V in mol/s, duties in watts
//! (W). Tolerances (stated): 1e-6 absolute on compositions,
//! 2e-3 K absolute on temperatures, 1e-3 mol/s absolute on
//! flows, 1e-4 relative on duties, as in mesh_parity.rs;
//! internal closure at the Python battery's gates (material
//! residual below 1e-3 mol/s, summation below 1e-4, enthalpy
//! residual below 5 W).

use ccr::columns::RaoultThermo;
use ccr::columns_mesh::{mesh_absorber, mesh_stripper};

fn thermo_tdep() -> RaoultThermo {
    let abc = [(14.2706, 2730.9, -26.806), (14.3314, 3004.3, -33.111),
               (14.3748, 3237.52, -40.249)];
    let mut psat: Vec<Box<dyn Fn(f64) -> f64>> = Vec::new();
    for (a, b, c) in abc {
        psat.push(Box::new(move |t: f64| 1000.0 * (a - b / (t + c)).exp()));
    }
    let hl: Vec<Box<dyn Fn(f64) -> f64>> = (0..3)
        .map(|_| Box::new(|t: f64| 150.0 * (t - 300.0)) as Box<dyn Fn(f64) -> f64>)
        .collect();
    let hv: Vec<Box<dyn Fn(f64) -> f64>> = (0..3)
        .map(|_| Box::new(|t: f64| 30000.0 + 100.0 * (t - 300.0)) as Box<dyn Fn(f64) -> f64>)
        .collect();
    RaoultThermo { psat, hl, hv }
}

const STRIPPER_T: &[f64] = &[354.5910784050736, 346.82813123306346, 343.78114506888153, 342.62820004769145, 342.1884328421519, 342.0197277774205, 341.9548951742145, 341.9299732735345, 341.9203938028183];
const STRIPPER_X: &[&[f64]] = &[&[0.18398072788808192, 0.3669558298407689, 0.4490634422711492], &[0.2980014722242227, 0.3633680315753313, 0.33863049620044594], &[0.357639772760097, 0.3325752382172622, 0.30978498902264084], &[0.3832486179110221, 0.31386215681509905, 0.30288922527387896], &[0.39351617472768, 0.3055046826247365, 0.30097914264758346], &[0.39752961113001833, 0.30211619006312307, 0.30035419880685854], &[0.39908267153937915, 0.3007882647508122, 0.3001290637098085], &[0.39968119220905046, 0.30027425210332276, 0.30004455568762667], &[0.3999114654536289, 0.3000761902489255, 0.3000123442974456]];
const STRIPPER_L: &[f64] = &[6.000000000000003, 10.080846283842353, 10.029647364277375, 10.011539913097875, 10.004455370600501, 10.001694665315055, 10.000628520047075, 10.000218282566912, 10.00006059666147];
const STRIPPER_V: &[f64] = &[4.080846283842353, 4.029647364277375, 4.011539913097873, 4.0044553706005, 4.001694665315056, 4.000628520047076, 4.0002182825669115, 4.00006059666147, 4.0];
const STRIPPER_B: f64 = 6.000000000000003;
const STRIPPER_QR: f64 = 123025.06011584945;
const STRIPPER_V3_XB: &[f64] = &[0.2610952632777863, 0.34307291448545496, 0.3958318222367588];
const STRIPPER_V5_XB: &[f64] = &[0.07733014178766151, 0.3992799991415186, 0.5233898590708198];
const STRIPPER_N0_T: &[f64] = &[349.40045133865306];
