const STRIPPER_N0_QR: f64 = 121345.51877040492;
const ABSORBER_T: &[f64] = &[357.754129288288, 359.5692772739734, 360.77948852289614, 361.697674355132, 362.50856277965676, 363.36796629647563];
const ABSORBER_X: &[&[f64]] = &[&[0.1790697744858974, 0.24004956738244457, 0.580880658131658], &[0.16753610409232128, 0.2047272131351201, 0.6277366827725586], &[0.15965078734043425, 0.18394932915056136, 0.6563998835090044], &[0.15314725700647663, 0.17110473325695386, 0.6757480097365695], &[0.14659256796460304, 0.1633899817593183, 0.6900174502760786], &[0.13859246067787945, 0.15968508597732242, 0.7017224533447982]];
const ABSORBER_Y: &[&[f64]] = &[&[0.49077900825601517, 0.2565820456193821, 0.2526389461246028], &[0.48030853751619484, 0.2303812957123115, 0.28931016677149346], &[0.4715179619504256, 0.21415647623205794, 0.31432556181751675], &[0.46256517449333345, 0.20437224320023206, 0.33306258230643393], &[0.45157523319439236, 0.19959991356636092, 0.34882485323924634], &[0.435892136965099, 0.1997591851933487, 0.3643486778415523]];
const ABSORBER_L: &[f64] = &[12.529449181289994, 12.367649435784278, 12.384763491554658, 12.403889623538591, 12.42636032827196, 12.456247777543659];
const ABSORBER_V: &[f64] = &[9.838200254494282, 9.855314310264657, 9.874440442248583, 9.896911146981948, 9.926798596253645, 7.470550818709983];
const ABSORBER_GAS_RATE: f64 = 7.470550818709983;
const ABSORBER_LIQ_RATE: f64 = 12.529449181289994;

#[test]
fn mesh_stripper_parity() {
    let th = thermo_tdep();
    let r = mesh_stripper(&[0.4, 0.3, 0.3], 10.0, 8, 4.0, &th, 150e3, None, &[1.0]);
    let mut dt = 0.0f64;
    let mut dx = 0.0f64;
    let mut dl = 0.0f64;
    for j in 0..STRIPPER_T.len() {
        dt = dt.max((r.t[j] - STRIPPER_T[j]).abs());
        dl = dl.max((r.l[j] - STRIPPER_L[j]).abs()).max((r.v[j] - STRIPPER_V[j]).abs());
        for i in 0..3 {
            dx = dx.max((r.x[j][i] - STRIPPER_X[j][i]).abs());
        }
    }
    println!("stripper: max dT={dt:.3e} K, max dx={dx:.3e}, max dflow={dl:.3e} mol/s,               B={} (ref {}), Qr={} (ref {}), maxmat={:.3e} mol/s, maxenth={:.3e} W",
             r.b, STRIPPER_B, r.q_reboiler, STRIPPER_QR,
             r.max_material_residual_mol_s, r.max_enthalpy_residual_w);
    assert!(dt < 2e-3, "stripper dT {dt}");
    assert!(dx < 1e-6, "stripper dx {dx}");
    assert!(dl < 1e-3, "stripper dflow {dl}");
    assert!((r.b - STRIPPER_B).abs() < 1e-3);
    assert!((r.q_reboiler - STRIPPER_QR).abs() < 1e-4 * STRIPPER_QR.abs());
    assert!(r.max_material_residual_mol_s < 1e-3);
    assert!(r.max_enthalpy_residual_w < 5.0);
    assert!(r.max_summation_residual < 1e-4);
    assert!(r.overall_balance_residual_mol_s.abs() < 1e-3);
    // Directional gate of the Python battery, against the
    // Python values at vapour rates 3 and 5 mol/s.
    let r3 = mesh_stripper(&[0.4, 0.3, 0.3], 10.0, 8, 3.0, &th, 150e3, None, &[1.0]);
    let r5 = mesh_stripper(&[0.4, 0.3, 0.3], 10.0, 8, 5.0, &th, 150e3, None, &[1.0]);
    for i in 0..3 {
        assert!((r3.x_bottoms[i] - STRIPPER_V3_XB[i]).abs() < 1e-6, "stripper V=3 xB {i}");
        assert!((r5.x_bottoms[i] - STRIPPER_V5_XB[i]).abs() < 1e-6, "stripper V=5 xB {i}");
    }
    assert!(r3.x_bottoms[0] > r.x_bottoms[0] && r.x_bottoms[0] > r5.x_bottoms[0]);
    // Single-stage limit (zero trays), Python values; the
    // Python battery recomputes this limit independently.
    let r0 = mesh_stripper(&[0.4, 0.3, 0.3], 10.0, 0, 4.0, &th, 150e3, None, &[1.0]);
    assert!((r0.t[0] - STRIPPER_N0_T[0]).abs() < 2e-3, "stripper N=0 T {}", r0.t[0]);
    for i in 0..3 {
        assert!((r0.x[0][i] - STRIPPER_N0_X[0][i]).abs() < 1e-6, "stripper N=0 x {i}");
    }
    assert!((r0.q_reboiler - STRIPPER_N0_QR).abs() < 1e-4 * STRIPPER_N0_QR.abs());
}

#[test]
fn mesh_absorber_parity() {
    let th = thermo_tdep();
    let r = mesh_absorber(&[0.5, 0.3, 0.2], 10.0, 350.0, &[0.05, 0.15, 0.80],
                          10.0, 320.0, 6, &th, 150e3, &[1.0]);
    let mut dt = 0.0f64;
    let mut dx = 0.0f64;
    let mut dl = 0.0f64;
    for j in 0..ABSORBER_T.len() {
        dt = dt.max((r.t[j] - ABSORBER_T[j]).abs());
        dl = dl.max((r.l[j] - ABSORBER_L[j]).abs()).max((r.v[j] - ABSORBER_V[j]).abs());
        for i in 0..3 {
            dx = dx.max((r.x[j][i] - ABSORBER_X[j][i]).abs())
                .max((r.y[j][i] - ABSORBER_Y[j][i]).abs());
        }
    }
    println!("absorber: max dT={dt:.3e} K, max dx={dx:.3e}, max dflow={dl:.3e} mol/s,               gas rate={} (ref {}), liquid rate={} (ref {}),               maxmat={:.3e} mol/s, maxenth={:.3e} W",
             r.gas_out_rate_mol_s, ABSORBER_GAS_RATE, r.liquid_out_rate_mol_s,
             ABSORBER_LIQ_RATE, r.max_material_residual_mol_s, r.max_enthalpy_residual_w);
    assert!(dt < 2e-3, "absorber dT {dt}");
    assert!(dx < 1e-6, "absorber dx {dx}");
    assert!(dl < 1e-3, "absorber dflow {dl}");
    assert!((r.gas_out_rate_mol_s - ABSORBER_GAS_RATE).abs() < 1e-3);
    assert!((r.liquid_out_rate_mol_s - ABSORBER_LIQ_RATE).abs() < 1e-3);
    assert!(r.max_material_residual_mol_s < 1e-3);
    assert!(r.max_enthalpy_residual_w < 5.0);
    assert!(r.max_summation_residual < 1e-4);
    assert!(r.overall_balance_residual_mol_s.abs() < 1e-3);
    assert!(r.gas_out_comp[0] < 0.5, "absorber removes pentane: {}", r.gas_out_comp[0]);
}
